/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.setHeader();

        // 대분류 콤보에 값 셋팅
        await scwin.setCode();

        // 사용자 서식 명칭 리스트
        await scwin.myFormNmList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF51000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

