 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DisclsForm_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_DisclsForm.errorMsg) {
            await $c.win.alert("OnLoadCompleted => " + dts_DisclsForm.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF51000.dts_DisclsForm_OnLoadCompleted" });
    }
};

