/**
 * @method
 * @name grd_DisclsForm_onheadcheckclick
 * @description grd_DisclsForm onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_DisclsForm_onheadcheckclick = function(col, colid, bCheck) {
    try {
        let gcnt = dts_DisclsForm.getRowCount();
        if (gcnt > 0) {
            grd_DisclsForm.Redraw = false;
            dts_DisclsForm.setBroadcast(false);
            for (let i = 1; i <= gcnt; i++) {
                dts_DisclsForm.setCellData(i, "CHK_FLAG", bCheck);
            }
            dts_DisclsForm.setBroadcast(true, true);
            grd_DisclsForm.Redraw = true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF51000.grd_DisclsForm_onheadcheckclick" });
    }
};

