/**
 * @method
 * @name newSave
 * @description new Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newSave = async function() {
    if (txb_myFormNm.getValue() === '') {
        await $c.win.alert("사용자 서식 그룹 명칭을 입력하여 주십시요.");
        txb_myFormNm.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(txb_myFormNm, 20, "사용자 서식 그룹 명칭")) {
        txb_myFormNm.focus();
        return;
    }
    scwin.rtn = confirm('사용자 서식 명칭을 신규추가 하시겠습니까?');
    if (scwin.rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_newFormNm.setCellData(1, "USR_ID", scwin.gUsrId);
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/MyFormPage.do",
            ref : "dts_newFormNm",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (cmb_myFormNmList.getValue() === '') {
        await $c.win.alert("사용자 서식 그룹을 선택하여 주십시요");
        return;
    }
    const rtn = confirm('서식목록을 저장 하시겠습니까?');
    if (scwin.rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_FormList.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_FormList",
            action : "/MyFormPage.do",
            ref : "dts_myFormList",
            target : "trs_FormList=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkMaxLength1
 * @description check Max Length1 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength1 = async function(obj, size, lbl) {
    const overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name reSetCheck
 * @description 체크 초기화
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.reSetCheck = function(sval) {
    // 데이터셋 체크박스 초기화
    for (let i = 1; i <= sval.getRowCount(); i++) {
        sval.setCellData(i, "CHK_FLAG", 0);
    }
};

/**
 * @method
 * @name cntDatasetRowCheck
 * @description ---------------------------------------------------------------------------- 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. -------------------------------------------------------------------------------
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.cntDatasetRowCheck = function(sval) {
    let cCnt = 0;
    for (i = 1; i <= sval.getRowCount(); i++) {
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

// 선택추가

/**
 * @method
 * @name selectTakeOver
 * @description //선택해제 tmpInt++
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectTakeOver = async function() {
    let checkTcnt = 0;
    let checkFlag = "";
    const tmpInt = 1;
    scwin.gMsgCnt = 0;
    if ($c.frame.path("NoData") !== null) {
        await $c.win.closePopup();
    }
    if (!scwin.cntDatasetRowCheck(dts_DisclsForm)) {
        await $c.win.alert("추가 할 서식을 선택하여 주십시요");
    } else {
        dts_myFormList.setBroadcast(false);
        for (let i = 1; i <= dts_DisclsForm.getRowCount(); i++) {
            if (dts_DisclsForm.getCellData(i, "CHK_FLAG") === 1) {
                checkFlag = "T";
                if (dts_myFormList.getRowCount() === 0) {
                    checkTcnt++;
                    dts_myFormList.insertRow();
                    dts_myFormList.setCellData(tmpInt, "LD_MKT_TP_NM", dts_DisclsForm.getCellData(i, "LD_MKT_TP_NM"));
                    dts_myFormList.setCellData(tmpInt, "FORM_CD", dts_DisclsForm.getCellData(i, "FORM_CD"));
                    dts_myFormList.setCellData(tmpInt, "FORM_KOR_NM", dts_DisclsForm.getCellData(i, "FORM_KOR_NM"));
                    dts_myFormList.setCellData(tmpInt, "FORM_UPCLSS_NM", dts_DisclsForm.getCellData(i, "FORM_UPCLSS_NM"));
                    dts_myFormList.setCellData(tmpInt, "FORM_ADM_INST_TP_NM", dts_DisclsForm.getCellData(i, "FORM_ADM_INST_TP_NM"));
                    dts_myFormList.setCellData(tmpInt, "USE_NM", dts_DisclsForm.getCellData(i, "USE_NM"));
                    dts_myFormList.setCellData(tmpInt, "MYFORM_NM_SEQ", cmb_myFormNmList.getValue());
                    dts_myFormList.setCellData(tmpInt, "USR_ID", scwin.gUsrId);
                } else {
                    for (let j = 1; j <= dts_myFormList.getRowCount(); j++) {
                        if (dts_DisclsForm.getCellData(i, "FORM_CD") === dts_myFormList.getCellData(j, "FORM_CD")) {
                            checkFlag = "F";
                            scwin.gMsgCnt++;
                            break;
                        }
                    }
                    if (checkFlag === 'T') {
                        checkTcnt++;
                        dts_myFormList.insertRow(dts_myFormList.getRowPosition() - 1);
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "LD_MKT_TP_NM", dts_DisclsForm.getCellData(i, "LD_MKT_TP_NM"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "FORM_CD", dts_DisclsForm.getCellData(i, "FORM_CD"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "FORM_KOR_NM", dts_DisclsForm.getCellData(i, "FORM_KOR_NM"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "FORM_UPCLSS_NM", dts_DisclsForm.getCellData(i, "FORM_UPCLSS_NM"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "FORM_ADM_INST_TP_NM", dts_DisclsForm.getCellData(i, "FORM_ADM_INST_TP_NM"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "USE_NM", dts_DisclsForm.getCellData(i, "USE_NM"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "MYFORM_NM_SEQ", cmb_myFormNmList.getValue());
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "USR_ID", scwin.gUsrId);
                    }
                }
            }
        }
        dts_myFormList.setBroadcast(true, true);
        if (checkTcnt === 0) {
            await $c.win.alert("선택한 서식 모두 이미 추가되어 있습니다.");
        }
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!scwin.cntDatasetRowCheck(dts_myFormList)) {
        await $c.win.alert("삭제할 서식을 선택하여 주십시요");
    } else {
        dts_myFormList.setBroadcast(false);
        for (i = dts_myFormList.getRowCount(); i > 0; i--) {
            if (dts_myFormList.getCellData(i, "CHK_FLAG") === 1) {
                // alert("i ===== " + i);
                dts_myFormList.removeRow(i);
            }
        }
        dts_myFormList.setBroadcast(true, true);
    }
};

/**
 * @method
 * @name grd_DisclsForm_CanColumnPosChange
 * @description grd Discls Form Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_DisclsForm_CanColumnPosChange = function(row, colid) {
    return true;
};
